INSERT INTO `field_help_cache` VALUES
(1,'home','{\"metadata\": {\"required_fields\": [{\"name\": \"reporting_period_start\", \"label\": \"Start Date\", \"state\": \"enabled\", \"required\": true, \"purpose\": \"Defines the opening date of the reporting period for the return.\"}, {\"name\": \"pbo_name\", \"label\": \"PBO Name\", \"state\": \"enabled\", \"required\": true, \"purpose\": \"Identifies the organization being reported and is central to record matching.\"}], \"sector_report_focus_fields\": [{\"name\": \"scope\", \"label\": \"Scope\", \"state\": \"enabled\", \"used_in_sector_report\": true, \"purpose\": \"Shows whether the PBO is national or international, which is used in grouped reporting.\"}, {\"name\": \"county\", \"label\": \"Counties Of Operation\", \"state\": \"enabled\", \"used_in_sector_report\": true, \"purpose\": \"Lists where the PBO operated during the reporting period for county-level reporting.\"}, {\"name\": \"sector[]\", \"label\": \"Project Sector\", \"state\": \"enabled\", \"used_in_sector_report\": true, \"purpose\": \"Captures the sector for each implementation row, which is a core sector-report dimension.\"}, {\"name\": \"project_county[]\", \"label\": \"Project County\", \"state\": \"locked_for_edit\", \"used_in_sector_report\": true, \"purpose\": \"Feeds county-level project analysis even when the edit page locks the visible control.\"}, {\"name\": \"project_beneficiaries_no[]\", \"label\": \"Project Beneficiaries\", \"state\": \"locked_for_edit\", \"used_in_sector_report\": true, \"purpose\": \"Supports beneficiary totals and sector impact summaries.\"}, {\"name\": \"project_spending_per_county[]\", \"label\": \"Project Spending Per County\", \"state\": \"locked_for_edit\", \"used_in_sector_report\": true, \"purpose\": \"Provides county-level spending values for the sector report output.\"}, {\"name\": \"project_duration_years[]\", \"label\": \"Project Duration\", \"state\": \"locked_for_edit\", \"used_in_sector_report\": true, \"purpose\": \"Helps describe the duration