INSERT INTO `field_help_interactions` VALUES
(1,'home','ASK A FIELD QUESTION. T','ask a field question. t','DISALLOWED_ACTION','FIELD_VALIDATION','validation-blocked','this action is disallowed on this form. The bot can only assist with allowed sector-report fields.',0.00033535,1,'2026-03-21 16:03:04'),
(2,'home','CONTACT POSITION','contact position','VALID_INPUT','FIELD_VALIDATION','validation-blocked','Contact Position is disallowed on this form. The bot can only assist with allowed sector-report fields.',0.00033535,1,'2026-03-21 16:03:20'),
(3,'home','PROJECT SECTOR','project sector','VALID_INPUT','FIELD_VALIDATION','validation-rules','`Project Sector` is allowed. Captures the sector for each implementation row, which is a core sector-report dimension. It maps to sector heading `2.3.1 Sectors of Operation`.',0.000859245,0,'2026-03-21 16:03:28'),
(4,'admin_view','WHICH PAYMENT FIELDS ARE COMMON','which payment fields are common','INVALID_INPUT','FAQ','faq-knowledge','Audit fields: Collects audit firm and auditor details only for audited organizations, but these are not core sector-report fields. Enabled only when Audited is Yes. Government tax waiver section: Avoids collecting government waiver fields when that section does not apply and keeps non-sector data out of the main reporting path. Disabled when the government sections are marked inactive.',0.00033535,0,'2026-03-26 05:48:46');
INSERT INTO `field_help_memory` VALUES
(1,'home','ASK A FIELD QUESTION. T','this action is disallowed on this form. The bot can only assist with allowed sector-report fields.','validation-blocked',NULL,'2026-03-21 16:03:04'),
(2,'home','CONTACT POSITION','Contact Position is disallowed on this form. The bot can only assist with allowed sector-report fields.','validation-blocked',NULL,'2026-03-21 16:03:20'),
(3,'home','PROJECT SECTOR','`Project Sector` is allowed. Captures the sector for each implementation row, which is a core sector-report dimension. It maps to sector heading `2.3.1 Sectors of Operation`.','validation-rules',NULL,'2026-03-21 16:03:28'),
(4,'admin_view','WHICH PAYMENT FIELDS ARE COMMON','Audit fields: Collects audit firm and auditor details only for audited organizations, but these are not core sector-report fields. Enabled only when Audited is Yes. Government tax waiver section: Avoids collecting government waiver fields when that section does not apply and keeps non-sector data out of the main reporting path. Disabled when the government sections are marked inactive.','faq-knowledge',NULL,'2026-03-26 05:48:46');
